<?php require_once '../includes/config.php'; require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action'];if($action==='add'){$st=$pdo->prepare('INSERT INTO coupons(code,type,amount,min_order,max_discount,expires_at,status) VALUES(?,?,?,?,?,?,1)');$st->execute([strtoupper(post_str('code')),post_str('type'),(float)$_POST['amount'],(float)$_POST['min_order'],$_POST['max_discount']!==''?(float)$_POST['max_discount']:null,post_str('expires_at')?:null]);flash('success','Coupon created.');}elseif($action==='toggle'){$pdo->prepare('UPDATE coupons SET status=1-status WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Coupon status updated.');}redirect('coupons.php');}$rows=$pdo->query('SELECT * FROM coupons ORDER BY id DESC')->fetchAll();$title='Coupons';require '../includes/header.php';?><div class="d-flex justify-content-between"><h1 class="section-title">Coupons & Offers</h1><button class="btn btn-purple" data-bs-toggle="modal" data-bs-target="#add">Add Coupon</button></div><div class="panel overflow-hidden mt-3"><div class="table-responsive"><table class="table"><thead><tr><th>Code</th><th>Type</th><th>Amount</th><th>Minimum</th><th>Expiry</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['code'])?></strong></td><td><?=e($r['type'])?></td><td><?=e($r['amount'])?></td><td><?=money($r['min_order'])?></td><td><?=e($r['expires_at'])?></td><td><?=$r['status']?'Active':'Inactive'?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="toggle" class="btn btn-sm btn-outline-purple">Toggle</button></form></td></tr><?php endforeach;?></tbody></table></div></div><div class="modal fade" id="add"><div class="modal-dialog"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="add"><div class="modal-header"><h5>Add coupon</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input class="form-control mb-2" name="code" placeholder="WELCOME10" required><select class="form-select mb-2" name="type"><option value="percent">Percentage</option><option value="fixed">Fixed</option></select><input class="form-control mb-2" name="amount" type="number" step="0.01" placeholder="Amount" required><input class="form-control mb-2" name="min_order" type="number" step="0.01" placeholder="Minimum order"><input class="form-control mb-2" name="max_discount" type="number" step="0.01" placeholder="Max discount (optional)"><input class="form-control" name="expires_at" type="date"></div><div class="modal-footer"><button class="btn btn-purple">Create</button></div></form></div></div></div><?php require '../includes/footer.php'; ?>